# Generated by Claude Opus 5.5 (claude.ai/code) · 2026-11-18
# Shared test setup, dot-sourced from each *.Tests.ps1 BeforeAll:
#   BeforeAll { . (Join-Path $PSScriptRoot '../TestHelpers.ps1') }
# Dependency-free: no docker, no network. Run everything with: Invoke-Pester -Path ./tests

$script:RepoDir = Split-Path -Parent $PSScriptRoot
Import-Module (Join-Path $script:RepoDir 'src/lib/BackupCommon.psm1') -Force
$script:TestsDir = $PSScriptRoot   # tests/ root: fixtures/ and ../src/ resolve from here
$script:Work = Join-Path ([System.IO.Path]::GetTempPath()) ("bkseqtest-" + [guid]::NewGuid().ToString('n'))
New-Item -ItemType Directory -Force -Path $script:Work | Out-Null

# a fake `restic` for archive-restic tests: prints a --json summary with a snapshot
# id, or exits non-zero when RESTIC_STUB_FAIL is set; when RESTIC_STUB_LOG is set it
# writes its working dir then its args (one per line) there. POSIX shell only.
$script:resticStub = Join-Path $script:Work 'restic-stub.sh'
$stubBody = @'
#!/bin/sh
if [ -n "$RESTIC_STUB_LOG" ]; then { pwd; printf '%s\n' "$@"; } > "$RESTIC_STUB_LOG"; fi
if [ -n "$RESTIC_STUB_FAIL" ]; then echo 'stub failure' >&2; exit 1; fi
echo '{"message_type":"summary","snapshot_id":"deadbeefcafe"}'
exit 0
'@
Set-Content -LiteralPath $script:resticStub -NoNewline -Value ($stubBody -replace "`r", '')
if (-not $IsWindows) { & chmod '+x' $script:resticStub }

function New-SpoolTestEnv {
    # Fresh event log + spool root + engine paths for one whole-run test.
    param([string]$Prefix = 'lc')
    $n = [guid]::NewGuid().ToString('n').Substring(0, 8)
    $root = Join-Path $script:Work "$Prefix-$n"
    $ev = Join-Path $script:Work "$Prefix-$n.jsonl"
    return @{
        N     = $n
        Ev    = $ev
        Root  = $root
        Paths = @{ BaseDir = $script:TestsDir; EventsPath = $ev; LockPath = ($root + '.lock'); SpoolRoot = $root }
    }
}

function Remove-TestWork {
    if ($script:Work -and (Test-Path -LiteralPath $script:Work)) {
        Remove-Item -LiteralPath $script:Work -Recurse -Force -ErrorAction SilentlyContinue
    }
}
